mapper.select:
SELECT M.STUDENTID, C.CLUBNUM, H.REGDATE, M.NAME, M.MAJOR, M.EMAIL1, M.EMAIL2, M.PHONE, C.CLUBNAME
FROM MEMBER M JOIN CLUBMEMBER H ON M.STUDENTID = H.STUDENTID JOIN CLUB C ON C.CLUBNUM = H.CLUBNUM
WHERE H.STUDENTID = #{studentId} AND H.CLUBNUM = #{clubNum}

SELECT M.STUDENTID, C.CLUBNUM, H.REGDATE, M.NAME, M.MAJOR, M.EMAIL1, M.EMAIL2, M.PHONE, C.CLUBNAME
FROM MEMBER M JOIN CLUBMEMBER H ON M.STUDENTID = H.STUDENTID JOIN CLUB C ON C.CLUBNUM = H.CLUBNUM
WHERE H.CLUBNUM = #{clubNum}
